from pathlib import Path
root=Path('/mnt/data/nk168_work')

graph=root/'src/organism/system/CausalLifeGraph.ts'
graph.write_text(r'''/**
 * BIG PASS 168 — Causal Life Graph.
 *
 * A bounded causal autobiographical graph over existing organism signals.
 * It is deliberately a projection/index, not a second memory database.
 * Each node points back to an existing entity (event, memory, emotion, value,
 * goal, action, outcome, self-change) and edges preserve directional lineage.
 */
export type LifeNodeKind='experience'|'emotion'|'memory'|'belief'|'value'|'goal'|'decision'|'action'|'outcome'|'learning'|'self-change';
export type LifeEdgeKind='interpreted-as'|'evoked'|'encoded-as'|'retrieved-for'|'supported'|'contradicted'|'pursued'|'selected'|'resulted-in'|'learned-from'|'changed-by';
export interface LifeNode{ id:string; kind:LifeNodeKind; refId:string; label:string; tick:number; at:number; confidence01:number; external01:number; metadata:Record<string,unknown>; }
export interface LifeEdge{ id:string; fromId:string; toId:string; kind:LifeEdgeKind; strength01:number; evidence01:number; tick:number; at:number; }
export interface CausalLifeGraphState{ version:1; nodes:LifeNode[]; edges:LifeEdge[]; totalNodes:number; totalEdges:number; observedChains:number; completeChains:number; chainCoverage01:number; meanEvidence01:number; lastAt:number; }
const clamp=(x:number)=>Math.max(0,Math.min(1,Number.isFinite(x)?x:0));
const clean=(x:unknown,n=160)=>String(x??'').trim().replace(/\s+/g,' ').slice(0,n);
const hash=(s:string)=>{let h=2166136261>>>0;for(const c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619)>>>0;}return h.toString(16).padStart(8,'0');};
const empty=():CausalLifeGraphState=>({version:1,nodes:[],edges:[],totalNodes:0,totalEdges:0,observedChains:0,completeChains:0,chainCoverage01:0,meanEvidence01:0,lastAt:0});
const chainKinds:LifeNodeKind[]=['experience','emotion','memory','decision','action','outcome','learning','self-change'];
export class CausalLifeGraph{
 private state=empty(); private nodeByRef=new Map<string,string>();
 restore(raw?:Partial<CausalLifeGraphState>|null){const d=empty(),r=raw??{};this.state={...d,...r,version:1,nodes:Array.isArray(r.nodes)?r.nodes.slice(0,768):[],edges:Array.isArray(r.edges)?r.edges.slice(0,1536):[]};this.rebuildIndex();this.recompute();}
 snapshot(){return structuredClone(this.state);}
 private rebuildIndex(){this.nodeByRef.clear();for(const n of this.state.nodes)this.nodeByRef.set(`${n.kind}:${n.refId}`,n.id);}
 upsertNode(input:{kind:LifeNodeKind;refId:string;label?:string;tick:number;at?:number;confidence01?:number;external01?:number;metadata?:Record<string,unknown>}):LifeNode{
   const ref=clean(input.refId,180)||`${input.kind}:${input.tick}`;const key=`${input.kind}:${ref}`;const existingId=this.nodeByRef.get(key);const at=Number(input.at??Date.now());
   if(existingId){const n=this.state.nodes.find(x=>x.id===existingId);if(n){n.label=clean(input.label??n.label);n.tick=Math.max(0,Math.floor(input.tick));n.at=at;n.confidence01=clamp(input.confidence01??n.confidence01);n.external01=clamp(input.external01??n.external01);n.metadata={...n.metadata,...(input.metadata??{})};this.state.lastAt=at;return structuredClone(n);}}
   const node:LifeNode={id:`clg:${input.kind}:${hash(ref)}:${Math.max(0,Math.floor(input.tick))}`,kind:input.kind,refId:ref,label:clean(input.label??ref),tick:Math.max(0,Math.floor(input.tick)),at,confidence01:clamp(input.confidence01??.5),external01:clamp(input.external01??0),metadata:{...(input.metadata??{})}};
   this.state.nodes.unshift(node);if(this.state.nodes.length>768)this.state.nodes=this.state.nodes.slice(0,768);this.nodeByRef.set(key,node.id);this.state.totalNodes+=1;this.state.lastAt=at;return structuredClone(node);
 }
 link(from:{kind:LifeNodeKind;refId:string},to:{kind:LifeNodeKind;refId:string},kind:LifeEdgeKind,strength01:number,evidence01:number,tick:number,at?:number){const fromId=this.nodeByRef.get(`${from.kind}:${clean(from.refId,180)}`),toId=this.nodeByRef.get(`${to.kind}:${clean(to.refId,180)}`);if(!fromId||!toId||fromId===toId)return null;const a=Number(at??Date.now());const existing=this.state.edges.find(e=>e.fromId===fromId&&e.toId===toId&&e.kind===kind);if(existing){existing.strength01=Math.max(existing.strength01,clamp(strength01));existing.evidence01=Math.max(existing.evidence01,clamp(evidence01));existing.tick=Math.max(existing.tick,Math.floor(tick));existing.at=a;return structuredClone(existing);}const e:LifeEdge={id:`clg-edge:${hash(`${fromId}|${toId}|${kind}`)}:${Math.max(0,Math.floor(tick))}`,fromId,toId,kind,strength01:clamp(strength01),evidence01:clamp(evidence01),tick:Math.max(0,Math.floor(tick)),at:a};this.state.edges.unshift(e);if(this.state.edges.length>1536)this.state.edges=this.state.edges.slice(0,1536);this.state.totalEdges+=1;this.state.lastAt=a;this.recompute();return structuredClone(e);}
 recordCycle(input:{tick:number;at?:number;experience?:{id:string;label:string;confidence01?:number;external01?:number};emotion?:{id:string;label:string;confidence01?:number;external01?:number};memory?:{id:string;label:string;confidence01?:number;external01?:number};decision?:{id:string;label:string;confidence01?:number};action?:{id:string;label:string;confidence01?:number};outcome?:{id:string;label:string;confidence01?:number;external01?:number};learning?:{id:string;label:string;confidence01?:number};selfChange?:{id:string;label:string;confidence01?:number}}){const at=Number(input.at??Date.now());const refs:{kind:LifeNodeKind;id:string;label:string;confidence01?:number;external01?:number}[]=[];if(input.experience)refs.push({kind:'experience',id:input.experience.id,label:input.experience.label,confidence01:input.experience.confidence01,external01:input.experience.external01});if(input.emotion)refs.push({kind:'emotion',id:input.emotion.id,label:input.emotion.label,confidence01:input.emotion.confidence01,external01:input.emotion.external01});if(input.memory)refs.push({kind:'memory',id:input.memory.id,label:input.memory.label,confidence01:input.memory.confidence01,external01:input.memory.external01});if(input.decision)refs.push({kind:'decision',id:input.decision.id,label:input.decision.label,confidence01:input.decision.confidence01});if(input.action)refs.push({kind:'action',id:input.action.id,label:input.action.label,confidence01:input.action.confidence01});if(input.outcome)refs.push({kind:'outcome',id:input.outcome.id,label:input.outcome.label,confidence01:input.outcome.confidence01,external01:input.outcome.external01});if(input.learning)refs.push({kind:'learning',id:input.learning.id,label:input.learning.label,confidence01:input.learning.confidence01});if(input.selfChange)refs.push({kind:'self-change',id:input.selfChange.id,label:input.selfChange.label,confidence01:input.selfChange.confidence01});for(const r of refs)this.upsertNode({kind:r.kind,refId:r.id,label:r.label,tick:input.tick,at,confidence01:r.confidence01,external01:r.external01});
   const pairs:Array<[LifeNodeKind,LifeNodeKind,LifeEdgeKind]>= [['experience','emotion','evoked'],['experience','memory','encoded-as'],['memory','decision','retrieved-for'],['emotion','decision','interpreted-as'],['decision','action','selected'],['action','outcome','resulted-in'],['outcome','learning','learned-from'],['learning','self-change','changed-by']];
   for(const [a,b,k] of pairs){const x=refs.find(r=>r.kind===a),y=refs.find(r=>r.kind===b);if(x&&y)this.link({kind:a,refId:x.id},{kind:b,refId:y.id},k,.68,.66,input.tick,at);}
   this.recompute();return this.snapshot();}
 private recompute(){const ids=new Set(this.state.nodes.map(n=>n.id));this.state.edges=this.state.edges.filter(e=>ids.has(e.fromId)&&ids.has(e.toId));const evidence=this.state.edges.length?this.state.edges.reduce((s,e)=>s+e.evidence01,0)/this.state.edges.length:0;const byTick=new Map<number,Set<LifeNodeKind>>();for(const n of this.state.nodes){const s=byTick.get(n.tick)??new Set<LifeNodeKind>();s.add(n.kind);byTick.set(n.tick,s);}let complete=0;for(const s of byTick.values()){if(chainKinds.every(k=>s.has(k)))complete++;}this.state.observedChains=byTick.size;this.state.completeChains=complete;this.state.chainCoverage01=clamp(complete/Math.max(1,byTick.size));this.state.meanEvidence01=clamp(evidence);}
 summary(){const s=this.state;return {nodes:s.nodes.length,edges:s.edges.length,totalNodes:s.totalNodes,totalEdges:s.totalEdges,observedChains:s.observedChains,completeChains:s.completeChains,chainCoverage01:s.chainCoverage01,meanEvidence01:s.meanEvidence01,lastAt:s.lastAt};}
 chainForTick(tick:number){const nodes=this.state.nodes.filter(n=>n.tick===Math.floor(tick));const ids=new Set(nodes.map(n=>n.id));return {nodes:structuredClone(nodes),edges:structuredClone(this.state.edges.filter(e=>ids.has(e.fromId)&&ids.has(e.toId)))};}
}
export const defaultCausalLifeGraph=()=>empty();
''',encoding='utf-8')

